require_once '../../config/db.php'; if(session_status()===PHP_SESSION_NONE)session_start(); if(!isset($_SESSION['user_id']))redirect('../../index.php');
$id=(int)($_GET['id']??0);$notice=$error='';
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['record_payment'])){verify_csrf();try{$amount=round((float)$_POST['amount'],2);$accountId=(int)$_POST['account_id'];$pdo->beginTransaction();$s=$pdo->prepare("SELECT invoice_number,contact_id,grand_total,amount_paid,status FROM invoices WHERE id=? FOR UPDATE");$s->execute([$id]);$locked=$s->fetch();if(!$locked||in_array($locked['status'],['paid','voided'],true))throw new RuntimeException('This invoice cannot receive a payment.');$balance=round($locked['grand_total']-$locked['amount_paid'],2);if($amount<=0||$amount>$balance)throw new RuntimeException('Payment must be greater than zero and no more than the outstanding balance.');$s=$pdo->prepare('SELECT ledger_account_id FROM accounts WHERE id=? AND is_active=1 FOR UPDATE');$s->execute([$accountId]);$ledgerId=(int)$s->fetchColumn();if(!$ledgerId)$ledgerId=(int)$pdo->query("SELECT id FROM chart_of_accounts WHERE account_code='1000'")->fetchColumn();$pdo->prepare("INSERT INTO payments(invoice_id,contact_id,account_id,payment_type,payment_date,amount,payment_method,reference_number,notes) VALUES(?,?,?,'inbound',?,?,?,?,?)")->execute([$id,$locked['contact_id'],$accountId,$_POST['payment_date'],$amount,trim((string)$_POST['payment_method']),trim((string)$_POST['reference_number']),trim((string)$_POST['notes'])]);$paymentId=(int)$pdo->lastInsertId();$pdo->prepare('UPDATE accounts SET current_balance=current_balance+? WHERE id=?')->execute([$amount,$accountId]);$newPaid=round($locked['amount_paid']+$amount,2);$status=$newPaid>=$locked['grand_total']?'paid':'partial';$pdo->prepare('UPDATE invoices SET amount_paid=?,status=? WHERE id=?')->execute([$newPaid,$status,$id]);$ar=(int)$pdo->query("SELECT id FROM chart_of_accounts WHERE account_code='1200'")->fetchColumn();post_journal($pdo,$_POST['payment_date'],trim((string)$_POST['reference_number'])?:'PAY-'.$paymentId,'Payment for '.$locked['invoice_number'],[['account_id'=>$ledgerId,'debit'=>$amount,'credit'=>0],['account_id'=>$ar,'contact_id'=>$locked['contact_id'],'debit'=>0,'credit'=>$amount]],'payment',$paymentId);$pdo->commit();redirect('view_invoice.php?id='.$id.'&paid=1');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}}
$s=$pdo->prepare('SELECT i.*,c.*,cur.symbol FROM invoices i JOIN contacts c ON c.id=i.contact_id JOIN currencies cur ON cur.code=i.currency_code WHERE i.id=?');$s->execute([$id]);$invoice=$s->fetch();if(!$invoice){http_response_code(404);exit('Invoice not found.');}$s=$pdo->prepare('SELECT * FROM invoice_lines WHERE invoice_id=? ORDER BY id');$s->execute([$id]);$lines=$s->fetchAll();$s=$pdo->prepare('SELECT p.*,a.account_name FROM payments p JOIN accounts a ON a.id=p.account_id WHERE p.invoice_id=? ORDER BY payment_date DESC,id DESC');$s->execute([$id]);$payments=$s->fetchAll();$accounts=$pdo->query('SELECT id,account_name,current_balance FROM accounts WHERE is_active=1 ORDER BY account_name')->fetchAll();$balance=$invoice['grand_total']-$invoice['amount_paid'];
require_once '../includes/header.php';require_once '../includes/sidebar.php';
?>
