<?php if($balance>0&&$invoice['status']!=='voided'):?><form method="post" class="bg-white border rounded-2xl p-6 mt-7 print:hidden"><?=csrf_field()?><h3 class="font-bold text-lg mb-4">Record payment</h3><div class="grid md:grid-cols-3 gap-4"><label class="text-sm">Amount<input name="amount" type="number" step="0.01" min="0.01" max="<?=$balance?>" value="<?=number_format($balance,2,'.','')?>" required class="block mt-1 w-full border rounded-lg px-3 py-2"></label><label class="text-sm">Deposit account<select name="account_id" required class="block mt-1 w-full border rounded-lg px-3 py-2 bg-white"><?php foreach($accounts as $a):?><option value="<?=$a['id']?>"><?=h($a['account_name'])?> (<?=money($pdo,$a['current_balance'])?>)</option><?php endforeach;?></select></label><label class="text-sm">Payment date<input name="payment_date" type="date" value="<?=date('Y-m-d')?>" required class="block mt-1 w-full border rounded-lg px-3 py-2"></label><label class="text-sm">Method<input name="payment_method" value="Bank transfer" class="block mt-1 w-full border rounded-lg px-3 py-2"></label><label class="text-sm">Reference<input name="reference_number" class="block mt-1 w-full border rounded-lg px-3 py-2"></label><label class="text-sm">Notes<input name="notes" class="block mt-1 w-full border rounded-lg px-3 py-2"></label></div><button name="record_payment" class="brand-bg text-white font-semibold px-5 py-2.5 rounded-lg mt-4">Record payment</button></form><?php endif;?>
